def open_lock(deadends, target):
    blocked = set(deadends)
    start = "0000"
    if start in blocked:
        return -1
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        state, moves = queue.popleft()
        if state == target:
            return moves
        for i in range(4):
            digit = int(state[i])
            for delta in (-1, 1):
                next_digit = (digit + delta) % 10
                neighbor = state[:i] + str(next_digit) + state[i + 1:]
                if neighbor not in blocked and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, moves + 1))
    return -1
